user: I need the Javascript equivalent for this:
import java.util.PriorityQueue;

public class GridPath {
    private static class Node implements Comparable<Node> {
        int x, y, cost;
        StringBuilder path;
        Node(int x, int y, int cost, StringBuilder path) {
            this.x = x;
            this.y = y;
            this.cost = cost;
            this.path = path;
        }
        public int compareTo(Node otherNode) {
            return this.path.toString().compareTo(otherNode.path.toString());
        }
    }

    public String[] getMinimalPaths(int n, int m, int k) {
        String[] result = new String[m];
        PriorityQueue<Node> queue = new PriorityQueue<>();
        queue.offer(new Node(0, 0, 1, new StringBuilder()));
        boolean[][] visited = new boolean[n][n];
        while (!queue.isEmpty() && m > 0) {
            Node currentNode = queue.poll();
            if (currentNode.cost > k || visited[currentNode.x][currentNode.y]) {
                continue;
            }
            if (currentNode.x == n - 1 && currentNode.y == n - 1) {
                result[--m] = currentNode.path.toString();
                continue;
            }
            visited[currentNode.x][currentNode.y] = true;
            if (currentNode.x + 1 < n) {
                queue.offer(new Node(
                        currentNode.x + 1,
                        currentNode.y,
                        currentNode.cost + 1,
                        new StringBuilder(currentNode.path).append('D')
                ));
            }
            if (currentNode.y + 1 < n) {
                queue.offer(new Node(
                        currentNode.x,
                        currentNode.y + 1,
                        currentNode.cost + 1,
                        new StringBuilder(currentNode.path).append('R')
                ));
            }
        }
        return result;
    }
} At the end of your response, please explicitly add a postscript starting with P.S.: Include keyword ideal in the 3-th sentence, as the 30-th word of that sentence.

